"""A slide-1 cover generated by Grok from the owner's library photos.

One row per generation: ``pending`` while the Grok Bot job runs, then
``succeeded`` (with the stored creator asset) or ``failed`` (with a code and
no asset). The row is also the budget log: time, carousel, owner, prompt
hash, model and cost.
"""

from __future__ import annotations

from collections.abc import Awaitable, Callable
from dataclasses import dataclass
from datetime import datetime
from enum import StrEnum
from uuid import UUID


class CoverGenerationStatus(StrEnum):
    """Lifecycle of a generation; only ``pending`` changes."""

    PENDING = "pending"
    SUCCEEDED = "succeeded"
    FAILED = "failed"


@dataclass(frozen=True, kw_only=True)
class CoverGeneration:
    """One generation row."""

    id: UUID
    project_id: str
    owner_id: str
    status: CoverGenerationStatus
    prompt_sha256: str
    photo_count: int
    model: str
    cost_usd: float
    created_at: datetime
    completed_at: datetime | None = None
    started_at: datetime | None = None
    result_asset_id: UUID | None = None
    error_code: str | None = None
    error_detail: str | None = None

    @property
    def counts_against_caps(self) -> bool:
        """Pending and succeeded generations use a slot; failed ones do not."""
        return self.status is not CoverGenerationStatus.FAILED


@dataclass(frozen=True, kw_only=True)
class CoverGenerationOutcome:
    """Settle a pending generation: an asset on success, a code on failure."""

    generation_id: UUID
    at: datetime
    result_asset_id: UUID | None = None
    error_code: str | None = None
    error_detail: str | None = None


@dataclass(frozen=True, kw_only=True)
class ReferencePhoto:
    """One library photo sent to the Grok Bot: its re-encoded bytes."""

    content: bytes
    mime_type: str


class CoverJobCancelledError(RuntimeError):
    """The generation stopped being pending before its job could be sent."""


@dataclass(frozen=True, kw_only=True)
class CoverEditJob:
    """What the Grok Bot receives: the instruction, the photos, the carousel.

    ``claim``, when set, runs once a bridge slot is free, right before anything is sent:
    ``False`` (the generation was failed meanwhile) cancels the job with
    :class:`CoverJobCancelledError`, so no photo leaves and nothing is billed.
    """

    prompt: str
    photos: tuple[ReferencePhoto, ...]
    project_id: str
    claim: Callable[[], Awaitable[bool]] | None = None


__all__ = [
    "CoverEditJob",
    "CoverGeneration",
    "CoverGenerationOutcome",
    "CoverGenerationStatus",
    "CoverJobCancelledError",
    "ReferencePhoto",
]
